//! Client certificates (REST APIs): `GenerateClientCertificate` makes a real self-signed X.509 certificate, valid for 365 days (the
//! developer guide: "The client certificate generated by API Gateway is valid for 365 days"), with a new RSA 2048 key, signed with
//! SHA-256 (the key size, the algorithm and the subject `CN=ApiGateway` are `(memory)`). Only the PEM of the certificate is ever
//! shown, as on AWS; the private key is kept (`_key`) so a backend can be configured with the very certificate a stage names. The
//! key is made outside the actor (`Inner::run`), because RSA key generation takes a moment.

use aws_wire::ApiError;
use serde_json::{Map, Value, json};

use crate::core::Core;
use crate::doc::{Doc, copy, public, put, with_tags};
use crate::errors::not_found;
use crate::patch::{Kind, apply, f};
use crate::req::{Req, Res, new_id, none};

/// How long a certificate is valid.
const VALID_SECS: i64 = 365 * 86_400;
/// The members the generator adds to the request before the actor sees it.
pub(crate) const PEM: &str = "_pem";
pub(crate) const KEY: &str = "_key";

/// A DER TLV.
fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    let n = content.len();
    if n < 0x80 {
        out.push(u8::try_from(n).unwrap_or(0));
    } else {
        let bytes: Vec<u8> = n
            .to_be_bytes()
            .into_iter()
            .skip_while(|b| *b == 0)
            .collect();
        out.push(0x80 | u8::try_from(bytes.len()).unwrap_or(0));
        out.extend(bytes);
    }
    out.extend_from_slice(content);
    out
}

fn seq(parts: &[Vec<u8>]) -> Vec<u8> {
    tlv(0x30, &parts.concat())
}

/// sha256WithRSAEncryption (1.2.840.113549.1.1.11) with its NULL parameters.
fn sha256_rsa() -> Vec<u8> {
    seq(&[
        tlv(
            0x06,
            &[0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b],
        ),
        vec![0x05, 0x00],
    ])
}

/// `CN=<cn>`.
fn name(cn: &str) -> Vec<u8> {
    let atv = seq(&[tlv(0x06, &[0x55, 0x04, 0x03]), tlv(0x0c, cn.as_bytes())]);
    seq(&[tlv(0x31, &atv)])
}

/// A UTCTime (`YYMMDDHHMMSSZ`), or a GeneralizedTime from 2050 on (RFC 5280, 4.1.2.5).
fn time(secs: i64) -> Vec<u8> {
    let s = aws_core::time::format_amz_date(secs); // YYYYMMDDTHHMMSSZ
    let digits: String = s.chars().filter(char::is_ascii_digit).collect();
    let year: i64 = digits.get(..4).and_then(|y| y.parse().ok()).unwrap_or(1970);
    if year < 2050 {
        tlv(
            0x17,
            format!("{}Z", digits.get(2..).unwrap_or_default()).as_bytes(),
        )
    } else {
        tlv(0x18, format!("{digits}Z").as_bytes())
    }
}

/// A positive serial number of 16 random bytes.
fn serial() -> Vec<u8> {
    let mut b = [0u8; 16];
    if getrandom::fill(&mut b).is_err() {
        b = [1; 16];
    }
    if let Some(first) = b.first_mut() {
        *first = (*first & 0x7f) | 0x01;
    }
    tlv(0x02, &b)
}

fn pem(der: &[u8]) -> String {
    let b64 = aws_core::base64::encode(der);
    let lines: Vec<&str> = b64
        .as_bytes()
        .chunks(64)
        .filter_map(|c| std::str::from_utf8(c).ok())
        .collect();
    format!(
        "-----BEGIN CERTIFICATE-----\n{}\n-----END CERTIFICATE-----\n",
        lines.join("\n")
    )
}

/// A new certificate valid from `now` for 365 days: its PEM, and its private key (PKCS #8 DER, base64).
pub(crate) fn make(now_secs: i64) -> Option<(String, String)> {
    use rsa::pkcs8::{EncodePrivateKey, EncodePublicKey};
    use rsa::sha2::Sha256;
    let key = rsa::PrivateKey::new(&mut getrandom::SysRng, 2048).ok()?;
    let spki = key
        .to_public_key()
        .to_public_key_der()
        .ok()?
        .as_bytes()
        .to_vec();
    let subject = name("ApiGateway");
    let tbs = seq(&[
        tlv(0xa0, &tlv(0x02, &[0x02])),
        serial(),
        sha256_rsa(),
        subject.clone(),
        seq(&[time(now_secs), time(now_secs + VALID_SECS)]),
        subject,
        spki,
    ]);
    let signature = key.pkcs1v15_sign::<Sha256>(&tbs).ok()?;
    let mut bits = vec![0u8];
    bits.extend(signature);
    let cert = seq(&[tbs, sha256_rsa(), tlv(0x03, &bits)]);
    let private = aws_core::base64::encode(key.to_pkcs8_der().ok()?.as_bytes());
    Some((pem(&cert), private))
}

fn no_cert() -> ApiError {
    // Recorded 2026-11-19.
    not_found("Invalid client certificate id specified")
}

/// What a read shows: never the key.
fn view(v: &Value) -> Value {
    with_tags(public(v))
}

/// `GenerateClientCertificate`, with the material `Inner::run` made.
pub(crate) fn generate(core: &mut Core, r: &Req) -> Res {
    let (Some(pem), Some(key)) = (r.opt(PEM), r.opt(KEY)) else {
        return Err(ApiError::internal(
            "the client certificate could not be made",
        ));
    };
    let id = new_id(6);
    let mut c = Map::new();
    c.insert("clientCertificateId".into(), json!(id));
    copy(&mut c, &r.body, &["description", "tags"]);
    c.insert("pemEncodedCertificate".into(), json!(pem));
    c.insert("createdDate".into(), json!(r.now_secs()));
    c.insert(
        "expirationDate".into(),
        json!(r.now_secs() + 365.0 * 86_400.0),
    );
    let shown = public(&Value::Object(c.clone()));
    c.insert(KEY.into(), json!(key));
    core.certs.insert(id, Doc(Value::Object(c)));
    Ok(shown.into())
}

/// The other client certificate operations, by name.
pub(crate) fn op(core: &mut Core, op: &str, r: &Req) -> Res {
    let id = r.s("clientCertificateId");
    match op {
        "GetClientCertificate" => core
            .certs
            .get(id)
            .map(|c| view(&c.0).into())
            .ok_or_else(no_cert),
        "GetClientCertificates" => {
            let items = core.certs.iter().map(|(_, c)| view(&c.0)).collect();
            Ok(crate::v1::page(items, r).into())
        }
        "UpdateClientCertificate" => {
            let slot = core.certs.get_mut(id).ok_or_else(no_cert)?;
            let mut v = slot.0.clone();
            apply(&mut v, &r.patches(), &[f("/description", Kind::Str)])?;
            slot.0 = v;
            Ok(view(&slot.0).into())
        }
        _ => core
            .certs
            .remove(id)
            .ok_or_else(no_cert)
            .and_then(|_| none()),
    }
}

/// Fills in what `GenerateClientCertificate` needs before the actor runs it.
pub(crate) async fn prepare(call: &mut aws_wire::service::Call, now_secs: i64) {
    let made = tokio::task::spawn_blocking(move || make(now_secs))
        .await
        .ok()
        .flatten();
    let mut body: Value = serde_json::from_str(&call.body).unwrap_or_else(|_| json!({}));
    if !body.is_object() {
        body = json!({});
    }
    if let Some((pem, key)) = made {
        put(&mut body, PEM, json!(pem));
        put(&mut body, KEY, json!(key));
    }
    call.body = body.to_string();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lengths_and_times_are_der() {
        assert_eq!(tlv(0x04, &[1, 2]), vec![0x04, 2, 1, 2]);
        let long = tlv(0x04, &[0u8; 300]);
        assert_eq!(long.get(..4), Some(&[0x04, 0x82, 0x01, 0x2c][..]));
        assert_eq!(time(0), tlv(0x17, b"700101000000Z"));
        assert_eq!(time(2_524_608_000), tlv(0x18, b"20500101000000Z"));
    }
}
